class ServiceTemplatesController
{
    private function ensureTableExists(PDO $db): void
    {
        $db->exec("CREATE TABLE IF NOT EXISTS service_templates (
            id INT AUTO_INCREMENT PRIMARY KEY,
            name VARCHAR(190) NOT NULL UNIQUE,
            checklist TEXT NULL,
            created_at DATETIME NOT NULL,
            updated_at DATETIME NULL
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    }

    public function index(): void
    {
        try {
            $db = Database::getConnection();
            $this->ensureTableExists($db);
            $templates = $db->query('SELECT * FROM service_templates ORDER BY name ASC')->fetchAll();
            
            // Decode checklist JSON for each template
            foreach ($templates as &$template) {
                $template['checklist'] = $template['checklist'] ? json_decode($template['checklist'], true) : [];
            }
            
            Response::json(['templates' => $templates]);
        } catch (\Throwable $e) {
            error_log('[SERVICE TEMPLATES INDEX ERROR] ' . $e->getMessage());
            Response::json(['error' => 'An internal error occurred while fetching service templates'], 500);
        }
    }

    public function store(array $data): void
    {
        $name = trim($data['name'] ?? '');
        $checklist = $data['checklist'] ?? [];

        if (empty($name)) {
            Response::json(['error' => 'Template name is required'], 400);
            return;
        }

        $db = Database::getConnection();
        $this->ensureTableExists($db);

        try {
            $stmt = $db->prepare('INSERT INTO service_templates (name, checklist, created_at) VALUES (:name, :checklist, NOW())');
            $stmt->execute([
                'name' => $name,
                'checklist' => json_encode($checklist)
            ]);
            $templateId = (int) $db->lastInsertId();
            SystemLog::write('service_templates', 'created', $templateId, $name, json_encode([
                'checklist_items' => is_array($checklist) ? count($checklist) : 0
            ]));
            Response::json(['id' => $templateId], 201);
        } catch (\Throwable $e) {
            if ($e->getCode() == 23000) {
                Response::json(['error' => 'A template with this name already exists'], 400);
            } else {
                error_log('[SERVICE TEMPLATES STORE ERROR] ' . $e->getMessage());
                Response::json(['error' => 'An internal error occurred while saving the service template'], 500);
            }
        }
    }

