        }

        $db = Database::getConnection();
        $this->ensureTableExists($db);

        // Fetch current state for diffing so the log shows what actually changed
        $existing = $db->prepare('SELECT name, checklist FROM service_templates WHERE id = :id');
        $existing->execute(['id' => $id]);
        $current = $existing->fetch();
        if (!$current) {
            Response::json(['error' => 'Template not found'], 404);
            return;
        }

        $changes = [];
        if ($current['name'] !== $name) {
            $changes['name'] = ['from' => $current['name'], 'to' => $name];
        }
        $oldChecklist = $current['checklist'] ? json_decode($current['checklist'], true) : [];
        $newChecklist = is_array($checklist) ? $checklist : [];
        $oldCount = is_array($oldChecklist) ? count($oldChecklist) : 0;
        $newCount = count($newChecklist);
        if (json_encode($oldChecklist) !== json_encode($newChecklist)) {
            $changes['checklist_items'] = ['from' => $oldCount, 'to' => $newCount];
        }

        try {
            $stmt = $db->prepare('UPDATE service_templates SET name = :name, checklist = :checklist, updated_at = NOW() WHERE id = :id');
            $stmt->execute([
                'name' => $name,
                'checklist' => json_encode($checklist),
                'id' => $id
            ]);
            if (!empty($changes)) {
                SystemLog::write('service_templates', 'updated', (int)$id, $name, json_encode($changes));
            }
            Response::json(['ok' => true]);
        } catch (\Throwable $e) {
            if ($e->getCode() == 23000) {
                Response::json(['error' => 'A template with this name already exists'], 400);
            } else {
                error_log('[SERVICE TEMPLATES UPDATE ERROR] ' . $e->getMessage());
                Response::json(['error' => 'An internal error occurred while updating the service template'], 500);
            }
        }
    }

    public function destroy(string $id): void
    {
        try {
            $db = Database::getConnection();
            $this->ensureTableExists($db);

            // Fetch name before deletion for logging
            $nameStmt = $db->prepare('SELECT name FROM service_templates WHERE id = :id');
            $nameStmt->execute(['id' => $id]);
            $template = $nameStmt->fetch();

            $stmt = $db->prepare('DELETE FROM service_templates WHERE id = :id');
            $stmt->execute(['id' => $id]);

            SystemLog::write('service_templates', 'deleted', (int)$id, $template['name'] ?? "Template #$id");

            Response::json(['ok' => true]);
        } catch (\Throwable $e) {
            error_log('[SERVICE TEMPLATES DESTROY ERROR] ' . $e->getMessage());
            Response::json(['error' => 'An internal error occurred while deleting the service template'], 500);
        }
